pub struct InnerForcingReference { pub err_norm: f64, pub h: f64 } // last accepted step
pub struct Rodas5pInnerForcingTarget { pub eta: f64, pub tau: f64, pub floor_active: bool }
const FORCING_ALPHA: f64 = 6.0 / 5.0; // (p+1)/(q+1) for RODAS5P (p=5, q=4)
const ROUNDOFF_RESIDUAL_MULT: f64 = 64.0;
pub fn rodas5p_inner_forcing_target_v3(flow_wrms: f64, rhs_wrms: f64, output_weight_l1: f64,
    h: f64, reference: Option<InnerForcingReference>) -> CoreResult<Rodas5pInnerForcingTarget> {
    // (input validation as in v2, lines 42-56)
    let cap = RODAS5P_INNER_RESIDUAL_HEURISTIC_FRACTION / output_weight_l1; // 0.02022 outer-WRMS
    let predicted_err = reference.map_or(1.0, |r| {
        let ratio = (h / r.h).abs().powi(RODAS5P_ESTIMATOR_ORDER as i32 + 1); // (h/h_ref)^5
        (r.err_norm * ratio).clamp(RODAS5P_INNER_FORCING_FLOOR, 1.0)
    });
    let tau_wanted = cap * predicted_err.powf(FORCING_ALPHA); // ~ h^6 at fixed rtol
    let roundoff = ROUNDOFF_RESIDUAL_MULT * f64::EPSILON * rhs_wrms.max(flow_wrms);
    let floor = roundoff.max(RODAS5P_INNER_FORCING_FLOOR);
    let tau = tau_wanted.max(floor); // never Err: graceful fallback (fix G2-2)
    let eta = if rhs_wrms > 0.0 { (tau / rhs_wrms).min(RODAS5P_INNER_FORCING_ETA_MAX) }
              else { RODAS5P_INNER_FORCING_ETA_MAX };
    Ok(Rodas5pInnerForcingTarget { eta, tau, floor_active: tau_wanted < floor })
}

